fun commitShape(tool: PaintTool, path: Path) {
    checkpoint(); drawShape(Canvas(bitmap), tool, path); edited()
}

if (tool in listOf(PaintTool.POLYGON, PaintTool.CURVE, PaintTool.SELECT, PaintTool.LASSO)) {
    options.addView(button(when (tool) { PaintTool.POLYGON -> ui(R.string.ui_finish_polygon); PaintTool.CURVE -> ui(R.string.ui_finish_curve); else -> ui(R.string.ui_commit_selection) }, "apply") {
        paintCanvas.applyPending()
    }, LinearLayout.LayoutParams(-1, dp(48)))
}
if(tool==PaintTool.POLYGON) options.addView(CheckBox(this).apply {
    tag="polygon_close";text=ui(R.string.ui_close_polygon);textSize=11f;isChecked=paintCanvas.closePolygon
    setOnCheckedChangeListener {_,checked -> paintCanvas.closePolygon=checked;paintCanvas.invalidate();scheduleAutosave()}
})
options.addView(button(ui(R.string.ui_how_to_use), "tool_help") {
    message(if(paintCanvas.cursorMode && tool in listOf(PaintTool.PENCIL,PaintTool.BRUSH,PaintTool.WATERCOLOR,PaintTool.ERASER)) ui(R.string.ui_cursor_help29) else tool.hint)
}, LinearLayout.LayoutParams(-1, dp(48)))

private fun curvePath() = Path().apply {
    moveTo(start.x, start.y)
    if (curveStage == 0) lineTo(end.x, end.y)
    else cubicTo(control1.x, control1.y, control2.x, control2.y, end.x, end.y)
}

fun applyPending() {
    if (trim != null) applyTrim()
    if (polygon.size >= 2) document.commitShape(if(closePolygon) PaintTool.POLYGON else PaintTool.LINE, polygonPath(closePolygon))
    polygon.clear();resetPolygonTap()
    if (curveStage > 0) document.commitShape(PaintTool.CURVE, curvePath())
    curveStage = 0
    document.finishSelection(); invalidate(); onStatus()

if (tool == PaintTool.CURVE && curveStage > 0) {
    if (curveStage == 1) control1 = point else control2 = point
} else {
    start = point; end = point; trace = Path().apply { moveTo(point.x, point.y) }
}

PaintTool.CURVE -> {
    if (curveStage == 1) control1 = point else if (curveStage == 2) control2 = point else end = point
}

PaintTool.CURVE -> {
    if (curveStage == 0) {
        end = point; control1 = PointF(start.x + (end.x - start.x) / 3, start.y + (end.y - start.y) / 3)
        control2 = PointF(start.x + 2 * (end.x - start.x) / 3, start.y + 2 * (end.y - start.y) / 3)
    } else if (curveStage == 1) control1 = point else control2 = point
    curveStage++
    if (curveStage == 3) applyPending()
}

private fun click(tag: String) { EditorTestNavigation.click(activity,tag) }
private fun tool(tool: PaintTool) { click("tool_${tool.name}"); assertEquals(tool, canvas.tool) }
private fun event(action: Int, x: Float, y: Float) {
    val p = canvas.toScreen(x, y)
    val event = MotionEvent.obtain(0, 10, action, p.x, p.y, 0)
    assertTrue(canvas.dispatchTouchEvent(event)); event.recycle()
}
private fun tap(x: Float, y: Float) { event(MotionEvent.ACTION_DOWN, x, y); event(MotionEvent.ACTION_UP, x, y); shadowOf(Looper.getMainLooper()).idle(); awaitIo() }
private fun drag(x1: Float, y1: Float, x2: Float, y2: Float) {
    event(MotionEvent.ACTION_DOWN, x1, y1)
    event(MotionEvent.ACTION_MOVE, (x1 + x2) / 2, (y1 + y2) / 2)
    event(MotionEvent.ACTION_UP, x2, y2)
}

@Test fun lineAndTwoBendCurveCommitAsSeparateUndoSteps() {
    tool(PaintTool.LINE); drag(10f, 10f, 70f, 10f); val lineInk = inkCount()
    tool(PaintTool.CURVE); drag(10f, 30f, 80f, 30f)
    drag(25f, 30f, 25f, 75f); drag(65f, 30f, 65f, 75f)
    assertTrue(inkCount() > lineInk + 30)
    assertTrue((45..70).any { y -> (20..75).any { x -> doc.bitmap.getPixel(x, y) != Color.WHITE } })
    click("undo"); assertEquals(lineInk, inkCount())
}
@Test fun finishCurveCommitsBeforeBothBendsWithoutDuplicatingTheUndoStep() {
    tool(PaintTool.CURVE)
    for (bends in 0..1) {
        doc.newImage(96, 96); canvas.fit()
        drag(10f, 30f, 80f, 30f)
        if (bends == 1) drag(25f, 30f, 25f, 75f)
        assertEquals(bends + 1, canvas.draftState().getInt("curve_stage"))
        assertTrue(canvas.hasPendingEdit)
        assertEquals(0, inkCount())
        // The real Finish curve button commits the current path, not an attachment.
        click("apply")
        assertFalse(canvas.hasPendingEdit)
        assertEquals(0, canvas.draftState().getInt("curve_stage"))
        val committed = inkCount()
        assertTrue(committed > 0)
        click("apply")
        assertEquals(committed, inkCount())
        click("undo"); assertEquals(0, inkCount())
        click("redo"); assertEquals(committed, inkCount())
    }
}
